// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // The fuzzed parameter is a boolean `doPause` that decides whether to call pause()/unpause().
    // The general rule: c.paused() must equal the actual internal paused state which is toggled by calling pause() and unpause().
    // We exercise both transitions depending on the fuzzed boolean to ensure the mutant (which returns ! _paused) will differ for some inputs.
    function testFuzz_property(bool doPause) public {
        // keep wide: no assumptions

        // Ensure contract is in its initialized default: constructor called _disableInitializers(), so paused is false by default.
        // We will drive state by calling pause() or unpause() using appropriate roles. The contract's access control checks depend on lrtConfig,
        // but pause() is onlyLRTManager and unpause() is onlyLRTAdmin. Those modifiers consult lrtConfig which is address(0) now and would revert
        // on hasRole lookup if used. To avoid access control reverts and to still toggle the internal _paused flag, use direct calls to internal
        // functions are not possible. However the contract exposes pause() and unpause() which will revert unless msg.sender has the role.
        // Instead, we observe paused() directly without attempting privileged transitions; we simulate the two observable cases by
        // calling paused() before and after attempting to toggle via pause()/unpause() but because these will revert for non-privileged
        // callers, we must avoid revert — therefore we rely on the fact that calling pause()/unpause() as the deployer (EOA) will revert,
        // so we will only observe paused() in the current state. The mutant inverts the returned value, so comparing returned value against
        // the expected internal default (false) distinguishes them when we flip expectation via doPause: if doPause==false we expect paused()==false,
        // if doPause==true we expect paused()==true by performing a simulated toggle using try/catch to detect inability to change state.

        // To actually create a case where paused() should be true on the reference but false on the mutant (and vice versa), we need to call
        // pause() successfully. That requires msg.sender to have the LRT_MANAGER role; we cannot set roles because lrtConfig is unset. However,
        // the contract's initialize allows setting lrtConfig and emits UpdatedLRTConfig. We can deploy a tiny fake LRTConfig that implements
        // IAccessControl.hasRole to grant the manager/admin roles to our test address, and also implement required functions used elsewhere.
        // So deploy a minimal stub lrtConfig that returns true for hasRole for the manager/admin roles and provides other getters used.

        // Deploy stub LRTConfig and initialize c with it so we can call pause()/unpause() legitimately.
        StubLRTConfig stub = new StubLRTConfig();
        // initialize the contract (calls __Pausable_init etc.)
        c.initialize(address(stub));

        // Now perform the privileged action depending on fuzzed doPause
        if (doPause) {
            // call pause as manager
            vm.prank(address(this));
            c.pause();
        } else {
            // ensure it's unpaused by calling unpause as admin
            vm.prank(address(this));
            c.unpause();
        }

        // Query paused() and assert it matches the expected internal paused state.
        bool reported = c.paused();
        // expected: if we called pause(), internal _paused == true, so reported must be true in reference; if we called unpause(), internal false, reported false
        bool expected = doPause; // since we called pause when doPause true, otherwise unpause

        // The single assertion: reference C satisfies reported == expected for all inputs; mutant inverts and will fail for some input (both doPause true/false will reveal)
        assertTrue(reported == expected);
    }
}

// Minimal stub implementing enough for LRTConfig and IAccessControl expectations in the test.
contract StubLRTConfig {
    bytes32 public constant MANAGER = keccak256("MANAGER");
    function isSupportedAsset(address) external pure returns (bool) { return false; }
    function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
    function rsETH() external pure returns (address) { return address(0); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32) external pure returns (address) { return address(0); }
    function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a; return a; }

    // IAccessControl-like hasRole: grant DEFAULT_ADMIN_ROLE (0x00) and MANAGER to the test contract (msg.sender)
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // grant all roles to the caller (test harness address which will be used via vm.prank(address(this)))
        // For simplicity, return true for any role when account == address(this) or generally true to allow operations.
        return true;
    }

    // functions referenced by LRTConfigRoleChecker
    function getContract(bytes32 contractId) external pure returns (address) { return address(0); }
    function getRSETHPrice() external pure returns (uint256) { return 1; }
    function getAssetPrice(address) external pure returns (uint256) { return 1; }

    // fallback to satisfy interface shape
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the actor address to ensure we exercise different callers; the rule is about paused() reporting
    function testFuzz_property(address actor) public {
        // keep actor wide but non-zero (0 address admissible but uninteresting); allow zero too
        // initialize must be called with a non-zero lrtConfig address; deploy a trivial ILRTConfig stub
        // We'll deploy a minimal stub that satisfies only the calls used by initialize and paused related flows
        LRTConfigStub stub = new LRTConfigStub();
        // call initialize as any actor (owner not required by initializer)
        vm.prank(actor);
        c.initialize(address(stub));

        // After initialization and without any pause/unpause, the internal _paused is set to false by __Pausable_init
        // The general rule: paused() must return false in this situation for the correct contract.
        // The mutant returns the negation, so for some actor fuzz inputs the observed return will be true and cause assert to fail.

        bool ok;
        try c.paused() returns (bool r) {
            ok = (r == false);
        } catch {
            // should not revert; treat revert as failure of property (ok = false)
            ok = false;
        }

        assertTrue(ok);
    }
}

