pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter is an address representing an arbitrary caller
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be non-zero to be a sensible caller
        vm.assume(caller != address(0));

        // Before initialization, constructor called _disableInitializers; initialize must be callable only on proxy but here we call initialize
        // We need an lrtConfig address; pass caller as dummy — UtilLib.checkNonZeroAddress only requires non-zero
        // Call initialize as the caller (fuzzed)
        vm.prank(caller);
        c.initialize(caller);

        // Immediately after initialization, the reference implementation sets _paused = false in __Pausable_init_unchained
        // So paused() should return false. We query paused() and assert it's false.
        // The mutant that inverts _paused will return true here for at least some inputs (any caller), so the assertion will fail on mutant for some fuzzed caller.

        bool ok;
        try c.paused() returns (bool v) {
            ok = (v == false);
        } catch {
            // If paused() reverts (should not), mark as failing the property
            ok = false;
        }

        // Single assertion: paused() must report false immediately after initialize for every admissible caller
        assertTrue(ok);
    }
}

