import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address to ensure paused() behavior is independent of caller
    function testFuzz_property(address caller) public {
        // admissible domain: any address is allowed (wide). Avoid zero address to be safe
        vm.assume(caller != address(0));

        // The reference contract after construction has been _disableInitializers() called in constructor,
        // so initialize would be needed to set up state properly. But paused() reads the internal _paused flag
        // which is false by default in PausableUpgradeable only after __Pausable_init is called. To exercise a
        // universally true property that the reference satisfies for all inputs we rely on calling paused()
        // without initialization; the reference implementation's paused() returns the internal _paused (default false)
        // while the mutant flips it to true. We fuzz the caller to ensure the view is independent of msg.sender.

        bool ok;
        // call paused() as the fuzzed caller
        vm.prank(caller);
        try c.paused() returns (bool val) {
            ok = val == false; // reference should report false (not paused) by default
        } catch {
            // If call reverts, treat as failure of reference property
            ok = false;
        }

        // Single assertion: reference always has paused() == false for any caller address immediately after deploy
        assertTrue(ok);
    }
}

