pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0xBEEF);

    function setUp() public {
        c = new C();
        // We need to initialize c so that updateLRTConfig can be called by an admin.
        // For the purposes of this invariant test, we will initialize with a non-zero lrtConfig address
        // by calling initialize with a dummy non-zero address. Use admin as msg.sender to become admin
        // but initialize is external and guarded by initializer; any caller can call it the first time.
        vm.prank(admin);
        c.initialize(address(0xCAFE));
        // After initialize, the admin (DEFAULT_ADMIN_ROLE) in the real system would be admin; in this test
        // the only access control used in updateLRTConfig is via IAccessControl on lrtConfig. However,
        // the contract's onlyLRTAdmin modifier checks IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
        // To ensure the call to updateLRTConfig succeeds in the reference contract (so the zero-address check applies),
        // we must set lrtConfig to a contract that reports admin has the DEFAULT_ADMIN_ROLE. We'll deploy a simple
        // LRTConfigMock and set it as current lrtConfig.
        LRTConfigMock mock = new LRTConfigMock(admin);
        vm.prank(admin);
        c.updateLRTConfig(address(mock));
    }

    // fuzzed param: candidate address to set as lrtConfig
    function testFuzz_property(address candidate) public {
        // keep wide domain but distinguish zero vs nonzero
        // no vm.assume to allow fuzzing find zero case

        // Call updateLRTConfig as admin (mock grants admin role to `admin`)
        bool ok;
        vm.prank(admin);
        try c.updateLRTConfig(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: On the reference implementation, any call that succeeds will never result in lrtConfig being zero;
        // moreover, attempting to set lrtConfig to zero should revert (so ok==false when candidate==address(0)).
        // We assert that if the call succeeded (ok==true) then the stored lrtConfig() getter is never zero.
        // This holds for the reference contract for all inputs; the mutant that removed the non-zero check will
        // allow ok==true and lrtConfig()==address(0) when candidate==address(0), causing this assertion to fail.
        address stored = c.lrtConfig();
        assertTrue(!(ok && stored == address(0)));
    }
}

// Minimal mock to satisfy access control checks in onlyLRTAdmin modifier.
contract LRTConfigMock {
    address public admin;
    constructor(address _admin) {
        admin = _admin;
    }
    function isSupportedAsset(address) external pure returns (bool) { return false; }
    function getContract(bytes32) external view returns (address) { return address(0); }
    function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
    function rsETH() external pure returns (address) { return address(0); }
    // Minimal IAccessControl.hasRole behavior: return true only for DEFAULT_ADMIN_ROLE (0x00) and our admin
    function hasRole(bytes32, address account) external view returns (bool) {
        return account == admin;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControlSimple {
    function grantRole(bytes32 role, address account) external;
}

// Minimal mock LRTConfig contract implementing only what C expects for admin checks.
contract MockLRTConfig is IAccessControlSimple {
    address public admin;
    mapping(bytes32 => mapping(address => bool)) public roles;
    constructor(address admin_) { admin = admin_; }
    function grantRole(bytes32 role, address account) external {
        require(msg.sender == admin, "only admin");
        roles[role][account] = true;
    }

    // dummy implementations used by C; safe to return zero addresses / defaults
    function rsETH() external view returns (address) { return address(0); }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function isSupportedAsset(address) external view returns (bool) { return false; }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
    function getContract(bytes32) external view returns (address) { return address(0); }
    function getSupportedAssetList() external view returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address) external view returns (uint256) { return 0; }
}

contract InvMutTest is Test {
    C c;
    MockLRTConfig cfg;

    bytes32 constant MANAGER = 0x00; // matches LRTConstants.MANAGER in behavior for role check

    function setUp() public {
        c = new C();
        // deploy a mock config with this test contract as admin so we can call updateLRTConfig
        cfg = new MockLRTConfig(address(this));
        // grant this test the admin role in the mock (mock requires admin to call grantRole)
        // mock's constructor sets 'admin' to address(this) so this call succeeds
        cfg.grantRole(0x00, address(this)); // grant DEFAULT_ADMIN_ROLE to this address
    }

    // fuzz param is the candidate new lrtConfig address
    function testFuzz_property(address newAddr) public {
        // Ensure we act as an LRT admin when calling updateLRTConfig
        // The mock's access-check in LRTConfigRoleChecker uses IAccessControl(address(lrtConfig)).hasRole(...)
        // Our MockLRTConfig doesn't implement hasRole; however, LRTConfigRoleChecker casts to IAccessControl and calls hasRole.
        // To satisfy the role checks without changing C, we rely on using the initialize path: set lrtConfig first to our mock,
        // so subsequent updateLRTConfig uses onlyLRTAdmin which will call hasRole on our mock. Our mock lacks hasRole; to avoid calling it,
        // we will call updateLRTConfig while the current lrtConfig is still unset — but onlyLRTAdmin would call hasRole on it.
        // To get a successful call path on the reference contract across inputs, we instead exploit that onlyLRTAdmin checks
        // hasRole on IAccessControl(address(lrtConfig)). That requires lrtConfig to be a contract implementing hasRole.
        // Therefore, we first set a valid lrtConfig by calling initialize with our mock's address so that internal lrtConfig is our mock.

        // initialize requires initializer and only called once; call initialize on c to set lrtConfig to cfg
        // Note: initialize requires a non-zero address in reference; cfg is non-zero.
        c.initialize(address(cfg));

        // Now c.lrtConfig() is of type ILRTConfig; to observe whether it's zero we can read the auto-generated getter lrtConfig()
        // The property we assert: after calling updateLRTConfig(newAddr) the stored lrtConfig getter must not be address(0) for the reference
        // because the reference reverts if newAddr == address(0). The mutant allows address(0).

        bool ok;
        try c.updateLRTConfig(newAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: for the correct contract, if the call succeeded, lrtConfig() must not be address(0);
        // if the call reverted (ok == false), that also means lrtConfig wasn't set to zero by the reference. Therefore the invariant
        // we assert is: either the call reverted, or the stored lrtConfig() != address(0).
        // The mutant that removed the non-zero check will succeed for newAddr == address(0) and leave lrtConfig == address(0),
        // violating this assertion for that fuzz input.

        assertTrue(!ok || address(c.lrtConfig()) != address(0));
    }
}

