pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0xBEEF);

    function setUp() public {
        c = new C();
    }

    // fuzzed param is the candidate new lrtConfig address; the fuzzer will try address(0) among others
    function testFuzz_property(address candidate) public {
        // we need to call updateLRTConfig as an LRT admin. The contract checks access via lrtConfig.hasRole.
        // To let the call succeed through onlyLRTAdmin, we deploy a helper contract that implements ILRTConfig
        // and returns that admin has DEFAULT_ADMIN_ROLE (0x00). We will set that helper as the current lrtConfig
        // by initializing the contract via initialize() with the helper address. The reference contract's initialize
        // requires a non-zero address, so candidate initialization is not fuzzed here; we only fuzz the subsequent
        // updateLRTConfig input (candidate). This keeps admissible domain wide and lets the fuzzer find candidate==address(0).

        // Deploy a simple LRTConfig stub that treats our `admin` as having the default admin role.
        LRTConfigStub stub = new LRTConfigStub(admin);

        // Initialize c with the stub (reference requires non-zero and will succeed)
        c.initialize(address(stub));

        // Sanity: the current lrtConfig getter (public variable) should equal the stub address now
        // Now we will call updateLRTConfig as `admin` to attempt to set lrtConfig to `candidate`.
        vm.prank(admin);
        bool ok;
        try c.updateLRTConfig(candidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: On the reference contract, a successful call must NOT result in lrtConfig == address(0).
        // Therefore, the universal property: after calling updateLRTConfig(candidate) as an admin, it's always true
        // that either the call reverted (ok == false) OR the stored lrtConfig() != address(0).
        // The mutant (which removed the non-zero check) will allow ok==true and lrtConfig==address(0) when candidate==address(0).

        // exactly one assertion reading c's public surface
        assertTrue(!ok || address(c.lrtConfig()) != address(0));
    }
}

// Minimal stub implementing enough of ILRTConfig/IAccessControl used by C to allow admin calls
contract LRTConfigStub {
    address public admin;
    constructor(address admin_) {
        admin = admin_;
    }

    // ILRTConfig getters used by C
    function rsETH() external pure returns (address) { return address(0x100); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function isSupportedAsset(address) external pure returns (bool) { return false; }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32) external pure returns (address) { return address(0); }
    function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a = new address[](0); return a; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }

    // minimal access control behavior: hasRole(DEFAULT_ADMIN_ROLE, acct) -> acct == admin
    function hasRole(bytes32 /*role*/, address account) external view returns (bool) {
        return account == admin;
    }

    // used by getContract in C.getRsETHAmountToMint path; but in our test we never call that path after init
    // provide stub for completeness
    function getAssetPrice(address) external pure returns (uint256) { return 1; }
    function assetPriceOracle(address) external pure returns (address) { return address(0); }
