pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract SimpleLRTConfigMock {
    // minimal mock implementing only what's needed by C's role checks and getters
    address public admin;
    mapping(bytes32 => address) public contracts;
    mapping(address => bool) public supported;
    mapping(address => uint256) public depositLimit;

    constructor(address admin_) {
        admin = admin_;
    }

    function hasRole(bytes32, address account) external view returns (bool) {
        // treat the preset admin as having any role queried (manager/admin)
        return account == admin;
    }

    function getContract(bytes32 contractId) external view returns (address) {
        return contracts[contractId];
    }

    function setContract(bytes32 contractId, address addr) external {
        contracts[contractId] = addr;
    }

    function isSupportedAsset(address asset) external view returns (bool) {
        return supported[asset];
    }

    function depositLimitByAsset(address asset) external view returns (uint256) {
        return depositLimit[asset];
    }

    function rsETH() external view returns (address) {
        return address(0);
    }
}

contract InvMutTest is Test {
    C c;
    SimpleLRTConfigMock mock;

    function setUp() public {
        c = new C();
        // deploy a mock lrtConfig with this test contract as admin
        mock = new SimpleLRTConfigMock(address(this));
    }

    // fuzz the address to set as new lrtConfig; the property: for an admin caller, calling updateLRTConfig
    // never results in c.lrtConfig() == address(0) on the correct contract (it reverts for zero input)
    function testFuzz_property(address newConfigAddr) public {
        // admissible domain: keep wide but we require the caller to be admin in the mock (this contract is admin)
        // no further restriction on newConfigAddr: fuzzer may choose address(0) which is the deciding value

        // ensure c is initialized to point at a sane lrtConfig first by calling initialize with mock
        // initialize requires non-zero address; pass mock address
        c.initialize(address(mock));

        // act as the admin (this contract) and call updateLRTConfig with the fuzzed address
        bool ok;
        try c.updateLRTConfig(newConfigAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // SINGLE assertion: on the correct (reference) contract, the call must NOT result in lrtConfig() == address(0).
        // That is, either the call reverted (ok == false) or it succeeded and c.lrtConfig() != address(0).
        // The mutant that removes the non-zero-address check can succeed with newConfigAddr == address(0),
        // making c.lrtConfig() == address(0) and thus violating this assertion for that input.
        address current = c.lrtConfig();
        assertTrue(!ok || current != address(0));
    }
}

