        } else {
            // keep arrayLen in [1, cap]
            arrayLen = (len % cap) + 1;
        }

        // build dynamic array of addresses of length arrayLen filled with non-zero addresses
        address[] memory arr = new address[](arrayLen);
        for (uint256 i = 0; i < arrayLen; ++i) {
            // use distinct non-zero addresses derived from i to avoid zero-address reverts
            arr[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp, address(this)))) | 1));
        }

        // Attempt to call addNodeDelegatorContractToQueue and record whether it reverts
        bool okAdd;
        try c.addNodeDelegatorContractToQueue(arr) {
            okAdd = true;
        } catch {
            okAdd = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, calling addNodeDelegatorContractToQueue with an array of length equal
        // to the reported maxNodeDelegatorCount should succeed. We implement this by asserting that if cap != 0 then okAdd is true and arrayLen == cap.
        // If cap == 0 (which should not happen in the reference), the assertion still requires okAdd == true when arrayLen == cap (but arrayLen==cap==0 is unreachable here),
        // so to keep a single assertTrue that the reference satisfies for all admissible inputs and the mutant breaks for some input,
        // we assert: if cap > 0 then okAdd && arrayLen == cap.

        bool propertyHolds = true;
        if (cap > 0) {
            // For the reference, adding exactly up to cap entries must succeed and we constructed arrayLen in [1,cap].
            // Ensure we actually tested the boundary by forcing arrayLen == cap whenever possible: if arrayLen != cap, call again with exact cap-sized array.
            if (arrayLen != cap) {
                address[] memory exact = new address[](cap);
                for (uint256 i = 0; i < cap; ++i) {
                    exact[i] = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp, address(this), cap))) | 1));
                }
                try c.addNodeDelegatorContractToQueue(exact) {
                    // success
                    propertyHolds = true;
                } catch {
                    propertyHolds = false;
                }
            } else {
                // we already attempted arrayLen in [1,cap]; require success only when arrayLen == cap
                // ensure okAdd is true (should be for reference)
                propertyHolds = okAdd;
            }
        } else {
            // cap == 0 is not expected for reference; but keep property vacuously true by requiring true
            propertyHolds = true;
        }

        assertTrue(propertyHolds);
    }
}

